cat > "${API_SRC}/app.py" <<'___MDFILE___'
"""Marlow Depot parts adviser.

    GET  /health    is the service up, and how big is the index it loaded
    GET  /whoami    which user the process runs as, and which credential it got
    POST /match     {"need": "..."} -> the part that answers it, plus a note

Everything is read from the environment, never hardcoded:

    DEPOT_INDEX_DIR   where the index lives      (default /index)
    DEPOT_LLM_URL     adviser backend base URL   (default http://llm:9000/v1)
    DEPOT_API_KEY     credential for the backend (must be supplied at run time)
    DEPOT_PORT        port to listen on          (default 8000)
"""

import hashlib
import json
import os
import pathlib
import sys

INDEX_DIR = pathlib.Path(os.environ.get("DEPOT_INDEX_DIR", "/index"))
MANIFEST = INDEX_DIR / "manifest.json"

# Checked before anything heavy is imported, so a container started ahead of
# the index build fails immediately and loudly instead of serving an empty
# catalogue.
if not MANIFEST.is_file():
    sys.stderr.write(
        "depot-api: no part index at %s - the index build has to finish "
        "before this service starts\n" % MANIFEST)
    raise SystemExit(3)

import getpass  # noqa: E402

import httpx  # noqa: E402
import pandas as pd  # noqa: E402
from fastapi import FastAPI  # noqa: E402
from pydantic import BaseModel  # noqa: E402

import depot_hash  # noqa: E402
import matching  # noqa: E402

VERSION = pathlib.Path(
    os.environ.get("DEPOT_VERSION_FILE", "version.txt")).read_text().strip()
LLM_URL = os.environ.get("DEPOT_LLM_URL", "http://llm:9000/v1")
API_KEY = os.environ.get("DEPOT_API_KEY", "")

MANIFEST_DATA = json.loads(MANIFEST.read_text())
PARTS_FRAME = pd.read_csv(INDEX_DIR / "parts_index.csv")
PARTS = [
    {
        "part_no": row["part_no"],
        "name": row["name"],
        "bin": row["bin"],
        "stock": int(row["stock"]),
        "price": float(row["price"]),
        "keywords": str(row["keywords"]).split(),
    }
    for row in PARTS_FRAME.to_dict("records")
]

ADVISER_SYSTEM = "You are the Marlow Depot parts adviser. Reply with one short line."

app = FastAPI(title="Marlow Depot parts adviser", version=VERSION)


class MatchRequest(BaseModel):
    need: str


def whoami_name():
    try:
        return getpass.getuser()
    except Exception:
        return "uid-%d" % os.getuid()


def key_fingerprint():
    if not API_KEY:
        return None
    return hashlib.sha256(API_KEY.encode("utf-8")).hexdigest()[:12]


def ask_adviser(need, part):
    prompt = ("Need: %s\nPart: %s %s\nBin: %s\nOn hand: %d"
              % (need, part["part_no"], part["name"], part["bin"],
                 part["stock"]))
    headers = {"Authorization": "Bearer %s" % (API_KEY or "none")}
    body = {
        "model": "depot-adviser",
        "messages": [
            {"role": "system", "content": ADVISER_SYSTEM},
            {"role": "user", "content": prompt},
        ],
    }
    reply = httpx.post("%s/chat/completions" % LLM_URL.rstrip("/"),
                       json=body, headers=headers, timeout=10.0)
    reply.raise_for_status()
    return reply.json()["choices"][0]["message"]["content"].strip()


@app.get("/health")
def health():
    return {
        "status": "ok",
        "version": VERSION,
        "indexed_parts": len(PARTS),
        "indexed_tokens": MANIFEST_DATA.get("tokens", 0),
        "catalog_fp": MANIFEST_DATA.get("catalog_fp"),
    }


@app.get("/whoami")
def whoami():
    return {
        "version": VERSION,
        "uid": os.getuid(),
        "user": whoami_name(),
        "key_fp": key_fingerprint(),
        "hash_fp": depot_hash.fingerprint(VERSION),
        "llm_url": LLM_URL,
    }


@app.post("/match")
def match(request: MatchRequest):
    part, score = matching.best_match(request.need, PARTS)
    if part is None:
        return {"part_no": None, "score": 0, "note": None,
                "need": request.need}
    note = ask_adviser(request.need, part)
    return {
        "part_no": part["part_no"],
        "name": part["name"],
        "bin": part["bin"],
        "stock": part["stock"],
        "score": score,
        "note": note,
        "need": request.need,
    }
___MDFILE___

cat > "${API_SRC}/indexer.py" <<'___MDFILE___'
"""Build the depot part index.

Runs once, writes the index into DEPOT_INDEX_DIR and exits. The API refuses to
start until the manifest this writes is there, so the index build always has to
finish first.

    DEPOT_INDEX_DIR   where to write the index   (default /index)
    DEPOT_CATALOG     catalogue to read          (default catalog/parts.json)
"""

import json
import os
import pathlib
import sys

import pandas as pd

import depot_hash
import matching

INDEX_DIR = pathlib.Path(os.environ.get("DEPOT_INDEX_DIR", "/index"))
CATALOG = pathlib.Path(os.environ.get("DEPOT_CATALOG", "catalog/parts.json"))
# Every part is expanded into its own token rows so the API can answer a need
# with a groupby instead of a scan. The depot has more bins than parts, so the
# frame is wider than the catalogue looks.
FANOUT = 180


def main():
    if not CATALOG.is_file():
        sys.stderr.write("indexer: no catalogue at %s\n" % CATALOG)
        return 2
    catalogue = json.loads(CATALOG.read_text())
    parts = catalogue["parts"]

    rows = []
    for part in parts:
        surface = " ".join([part["name"]] + list(part["keywords"]))
        for token in sorted(set(matching.tokens(surface))):
            rows.append({
                "part_no": part["part_no"],
                "name": part["name"],
                "bin": part["bin"],
                "stock": part["stock"],
                "price": part["price"],
                "keywords": " ".join(part["keywords"]),
                "token": token,
            })
    frame = pd.DataFrame(rows)
    # A little synthetic breadth so the shape of the frame matches what the
    # depot actually ships to its regional sites.
    frame = pd.concat([frame] * FANOUT, ignore_index=True)
    frame["token_weight"] = frame.groupby("token")["part_no"].transform("count")
    catalogue_frame = (frame
                       .drop_duplicates(subset=["part_no"])
                       .sort_values("part_no")
                       .loc[:, ["part_no", "name", "bin", "stock", "price",
                                "keywords"]])

    INDEX_DIR.mkdir(parents=True, exist_ok=True)
    catalogue_frame.to_csv(INDEX_DIR / "parts_index.csv", index=False)
    (INDEX_DIR / "tokens_index.csv").write_text(
        frame.drop_duplicates(subset=["part_no", "token"])
             .sort_values(["token", "part_no"])
             .loc[:, ["token", "part_no", "token_weight"]]
             .to_csv(index=False))

    fingerprint = depot_hash.fingerprint(
        "|".join(sorted(p["part_no"] for p in parts)))
    manifest = {
        "depot": catalogue.get("depot", "unknown"),
        "parts": int(len(catalogue_frame)),
        "tokens": int(frame["token"].nunique()),
        "catalog_fp": fingerprint,
    }
    # Written last. Its presence is what tells the API the index is complete.
    (INDEX_DIR / "manifest.json").write_text(json.dumps(manifest, indent=2))
    print("indexed %d parts, %d tokens, fingerprint %s"
          % (manifest["parts"], manifest["tokens"], fingerprint))
    return 0


if __name__ == "__main__":
    sys.exit(main())
___MDFILE___

cat > "${API_SRC}/matching.py" <<'___MDFILE___'
"""Token scoring the depot uses to pick a part for a stated need.

Shared by the indexer and the API so both rank a need the same way.
Standard library only - this module has to be importable anywhere.
"""

import re

MIN_TOKEN = 3
KEYWORD_WEIGHT = 3
NAME_WEIGHT = 1


def tokens(text):
    """Lowercase alphanumeric tokens of length >= MIN_TOKEN, in order."""
    return [t for t in re.split(r"[^a-z0-9]+", (text or "").lower())
            if len(t) >= MIN_TOKEN]


def need_tokens(need):
    """The distinct tokens of a stated need, sorted for stability."""
    return sorted(set(tokens(need)))


def score_one(need_set, keywords, name):
    """How well one part answers a need: keyword hits count triple."""
    return (KEYWORD_WEIGHT * len(need_set & set(keywords))
            + NAME_WEIGHT * len(need_set & set(tokens(name))))


def best_match(need, parts):
    """(part, score) for the best-scoring part, or (None, 0) if nothing scores.

    `parts` is a sequence of dicts with part_no, name and keywords. Ties go to
    the lower part number so the same need always resolves to the same part.
    """
    need_set = set(need_tokens(need))
    ranked = sorted(
        ((score_one(need_set, p["keywords"], p["name"]), p["part_no"])
         for p in parts),
        key=lambda pair: (-pair[0], pair[1]),
    )
    if not ranked or ranked[0][0] <= 0:
        return None, 0
    top_score, top_no = ranked[0]
    for part in parts:
        if part["part_no"] == top_no:
            return part, top_score
    return None, 0
